    const state = stream._readableState;
    const publicDecoder = state.decoder;
    const symbolDecoder = Reflect.ownKeys(state)
      .filter((key) => typeof key === "symbol")
      .map((key) => state[key])
      .find((value) => value?.lastChar != null);
